  title = 'Oskar Ablimit — Cloud, Security & AI Solutions Engineering',
  summary = 'Technical architecture, customer engineering, and hands-on implementation.',
  content_json = '{"eyebrow":"SENIOR SALES ENGINEER · CLOUD ARCHITECT · EDUCATOR","headline":"Cloud, security, and AI systems—explained clearly and built practically.","body":"I help technical and business teams evaluate architecture, reduce risk, and turn complex platforms into useful outcomes. My experience spans Cloudflare, AWS, AI agents, application security, and enterprise solution engineering.","actions":[{"label":"View technical work","href":"#projects"},{"label":"Explore capabilities","href":"#capabilities"}]}'
