UPDATE site_sections SET
  title = 'Technical depth. Customer clarity.',
  summary = 'A solutions engineer who can design, demonstrate, teach, and build.',
  content_json = '{"body":"I am a Senior Sales Engineer at Cloudflare and an Adjunct Professor at Yeshiva University. Across 9+ years at Cloudflare, AWS, Tencent Cloud, and Alibaba Cloud, I have worked with enterprise teams on cloud architecture, security, application modernization, and technical adoption. I complement customer-facing work with hands-on Python, Django, Workers, Durable Objects, D1, AI agent, and MCP projects.","highlights":["Senior Sales Engineer at Cloudflare","9+ years across cloud and enterprise technology","Master of Engineering in Cloud Computing","Adjunct Professor teaching graduate cloud computing","Cloudflare ACE and ASE accredited","AWS Solutions Architect Professional"]}'
WHERE id = 'about';

